{"path": "src/db.js", "content": "const mongoose = require('mongoose');
const dotenv = require('dotenv');
dotenv.config();

const uri = process.env.DOCUMENTDB_URI;
const dbName = process.env.DATABASE_NAME || 'sample_healthcare_15';

if (!uri) {
  console.error('DOCUMENTDB_URI is not set. See .env.example');
  process.exit(1);
}

let connection;

async function connect() {
  if (connection) return connection;
  connection = await mongoose.connect(uri, {
    dbName,
    // Connection tuning suggestions from documentdb-connection skill
    maxPoolSize: 20,
    minPoolSize: 0,
    serverSelectionTimeoutMS: 5000,
    socketTimeoutMS: 45000,
    retryWrites: true,
  });
  return connection;
}

module.exports = { connect, mongoose };
"}

{"path": "src/models/prescription.js", "content": "const { mongoose } = require('../db');
const { Schema } = mongoose;

const PrescriptionSchema = new Schema({
  patientId: { type: String, required: true, index: true },
  prescriptionId: { type: String, required: true, unique: true, index: true },
  drugName: { type: String, required: true, index: true },
  daysSupply: { type: Number, required: true },
  refillCountRemaining: { type: Number, required: true, default: 0 },
  lastFilledAt: { type: Date, required: true },
  active: { type: Boolean, default: true, index: true }
}, { timestamps: true });

// text index for simple medication name matching
PrescriptionSchema.index({ drugName: 'text' });

const Prescription = mongoose.models.Prescription || mongoose.model('Prescription', PrescriptionSchema);
module.exports = Prescription;
"}

